begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email,email_confirmed_at) values
('93700000-0000-4000-8000-000000000001','mail-member@example.test',now());
insert into public.events(id,organizer_id,title,description,start_time,end_time,location_type,status,registration_scope,timezone) values
('93800000-0000-4000-8000-000000000001','93700000-0000-4000-8000-000000000001','Gathering one','Synthetic event email contract',now()+interval '2 days',now()+interval '2 days 2 hours','virtual','approved','public','Asia/Kolkata');
insert into private.event_access_details(event_id,join_url) values
('93800000-0000-4000-8000-000000000001','https://example.test/private-credential');
insert into private.event_registrations(id,event_id,user_id,status) values
('93900000-0000-4000-8000-000000000001','93800000-0000-4000-8000-000000000001','93700000-0000-4000-8000-000000000001','confirmed');
insert into private.event_registrations(id,event_id,guest_email,guest_name,status,approved_at) values
('93900000-0000-4000-8000-000000000002','93800000-0000-4000-8000-000000000001','mail-guest@example.test','Email guest','waitlisted',now());
select ok(not has_table_privilege('authenticated','private.event_delivery_outbox','SELECT'),'Members cannot read queued recipient data');
select ok(not has_table_privilege('anon','private.event_delivery_outbox','INSERT'),'Visitors cannot enqueue arbitrary mail');
select ok(not has_function_privilege('authenticated','public.claim_event_delivery_batch(integer)','EXECUTE'),'Members cannot claim mail');
select ok(not has_function_privilege('anon','public.event_delivery_ready(uuid,uuid)','EXECUTE'),'Guests cannot inspect delivery leases');
select ok(not has_function_privilege('authenticated','public.complete_event_delivery(uuid,uuid,boolean,text,text)','EXECUTE'),'Members cannot settle mail');
select is((select count(*)::integer from private.event_delivery_outbox),4,'Registration transitions and future confirmed reminders are enqueued atomically');
select is((select communication_version from private.event_registrations where id='93900000-0000-4000-8000-000000000001'),1,'New registrations start at version one');
select lives_ok($$select private.enqueue_event_communication('93900000-0000-4000-8000-000000000001','registration')$$,'Repeated enqueue is safe');
select is((select count(*)::integer from private.event_delivery_outbox),4,'Repeated enqueue does not duplicate a notification');
set local role authenticated;
set local "request.jwt.claims"='{"role":"authenticated"}';
select throws_ok($$select * from public.claim_event_delivery_batch(10)$$,'42501',null,'A browser JWT cannot claim recipients');
reset role;
set local "request.jwt.claims"='{"role":"service_role"}';
create temp table claimed as select * from public.claim_event_delivery_batch(10);
select is((select count(*)::integer from claimed),2,'Only due registration jobs are claimed');
select is((select recipient_email from claimed where recipient_email='mail-guest@example.test'),'mail-guest@example.test','Verified guest registrations can receive transaction emails');
select is((select count(*)::integer from public.claim_event_delivery_batch(10)),0,'Another worker cannot claim live leases');
select ok((select bool_and(template_data::text not like '%private-credential%') from claimed),'Claims exclude private venue credentials');
select ok((select bool_and(template_data::text not like '%mail-guest%' and template_data::text not like '%Email guest%') from claimed),'Template payload excludes names and recipient emails');
select ok((select bool_and(public.event_delivery_ready(id,lease_token)) from claimed),'Valid current jobs pass preflight');
select ok(not has_function_privilege('authenticated','public.prepare_event_delivery(uuid,uuid,jsonb)','EXECUTE'),'Browsers cannot prepare arbitrary recipient mail');
select throws_ok($$select public.prepare_event_delivery(id,lease_token,jsonb_build_object('from','events@indusorbit.com','to',jsonb_build_array('different@example.test'),'subject','Notice','text','Safe event text','html','<p>Safe event text</p>')) from claimed limit 1$$,'22023',null,'Preparation cannot change the verified recipient');
create temp table prepared as select id,public.prepare_event_delivery(id,lease_token,jsonb_build_object('from','events@indusorbit.com','to',jsonb_build_array(recipient_email),'subject','Original notice','text','Safe event text','html','<p>Safe event text</p>')) as payload from claimed;
select is((select count(*)::integer from private.event_delivery_outbox where prepared_payload is not null),2,'The complete provider payload is frozen before sending');
select is((select public.prepare_event_delivery(c.id,c.lease_token,jsonb_build_object('from','changed-sender@example.test','to',jsonb_build_array(c.recipient_email),'subject','Changed renderer','text','Changed text','html','<p>Changed text</p>'))->>'subject' from claimed c limit 1),'Original notice','Template and sender changes cannot alter the payload under an existing idempotency key');
select throws_ok($$select public.complete_event_delivery((select id from claimed limit 1),gen_random_uuid(),true)$$,'22023',null,'A wrong lease cannot settle a job');
select throws_ok($$select public.complete_event_delivery(id,lease_token,null) from claimed limit 1$$,'22023',null,'Null delivery results are rejected');
select lives_ok($$select public.complete_event_delivery(id,lease_token,true,'synthetic-message') from claimed where recipient_email='mail-member@example.test'$$,'Successful provider response settles a job');
select is((select status from private.event_delivery_outbox where id=(select id from claimed where recipient_email='mail-member@example.test')),'delivered','Successful jobs are delivered');
select lives_ok($$select public.complete_event_delivery(id,lease_token,false,null,'raw-mail-guest@example.test') from claimed where recipient_email='mail-guest@example.test'$$,'Failed delivery schedules a bounded retry');
select is((select error_code from private.event_delivery_outbox where id=(select id from claimed where recipient_email='mail-guest@example.test')),'delivery_unconfirmed','Untrusted errors are reduced to fixed redacted codes');
update private.event_delivery_outbox set due_at=now()-interval '1 second' where status='pending' and kind='registration';
create temp table retried as select * from public.claim_event_delivery_batch(10);
select is((select id from retried limit 1),(select id from claimed where recipient_email='mail-guest@example.test'),'Retries preserve provider idempotency identity');
select is((select template_data from retried limit 1),(select template_data from claimed where recipient_email='mail-guest@example.test'),'Retry payload is immutable');
update private.event_registrations set status='confirmed' where id='93900000-0000-4000-8000-000000000002';
select is((select communication_version from private.event_registrations where id='93900000-0000-4000-8000-000000000002'),2,'Waitlist promotion advances registration version');
select ok(not (select public.event_delivery_ready(id,lease_token) from retried limit 1),'Promotion suppresses an obsolete leased waitlist email');
select is((select status from private.event_delivery_outbox where id=(select id from retried limit 1)),'suppressed','Superseded leased messages are terminal');
update private.event_registrations set checked_in_at=now() where id='93900000-0000-4000-8000-000000000001';
select is((select communication_version from private.event_registrations where id='93900000-0000-4000-8000-000000000001'),1,'Check-in does not emit duplicate registration mail');
update private.event_registrations set checked_in_at=null where id='93900000-0000-4000-8000-000000000001';
update public.events set start_time=now()+interval '3 days',end_time=now()+interval '3 days 2 hours' where id='93800000-0000-4000-8000-000000000001';
insert into private.event_edit_history(event_id,revision,actor_id,request_id,fingerprint,changed_fields,summary,reason) values
('93800000-0000-4000-8000-000000000001',1,'93700000-0000-4000-8000-000000000001',gen_random_uuid(),'synthetic','{startTime}','{}','Synthetic rescheduling reason');
select is((select count(*)::integer from private.event_delivery_outbox where kind='changed'),2,'Rescheduling enqueues each active attendee');
select is((select count(*)::integer from private.event_delivery_outbox where kind='reminder_24h' and event_revision=1),2,'Rescheduling creates reminders for the new revision');
create temp table changed as select * from public.claim_event_delivery_batch(10);
select is((select count(*)::integer from changed),2,'Old confirmations are suppressed; latest change messages are claimed');
select ok((select bool_and(template_data->>'kind'='changed') from changed),'Claim contains current change information');
select is((select count(*)::integer from private.event_delivery_outbox where kind like 'reminder_%' and event_revision=0 and status='suppressed'),4,'Old schedule reminders are suppressed');
update public.events set lifecycle='cancelled' where id='93800000-0000-4000-8000-000000000001';
select ok(not (select public.event_delivery_ready(id,lease_token) from changed limit 1),'Cancellation invalidates a leased event update');
create temp table cancellations as select * from public.claim_event_delivery_batch(10);
select is((select count(*)::integer from cancellations),2,'Cancellation messages cover both member and guest attendees');
select ok((select bool_and(template_data->>'kind'='cancelled') from cancellations),'Cancellation template is explicit');
select is((select count(*)::integer from private.event_delivery_outbox where kind like 'reminder_%' and status='pending'),0,'Cancelled events have no pending reminder delivery');
update private.event_delivery_outbox set attempt_count=5,leased_at=now()-interval '6 minutes' where id=(select id from cancellations limit 1);
select lives_ok($$select * from public.claim_event_delivery_batch(10)$$,'A crashed final attempt can be recovered');
select is((select status from private.event_delivery_outbox where id=(select id from cancellations limit 1)),'dead','Exhausted crashed leases become dead letters');
update private.event_delivery_outbox set leased_at=now()-interval '6 minutes',first_attempt_at=now()-interval '21 hours' where status='processing';
select lives_ok($$select * from public.claim_event_delivery_batch(10)$$,'Old ambiguous delivery is handled without resending');
select is((select count(*)::integer from private.event_delivery_outbox where status='processing'),0,'No retry occurs outside the provider idempotency window');
select is((select count(*)::integer from private.event_delivery_outbox where error_code='retry_window_exhausted'),2,'Exhaustion is recorded with a fixed operational code');
select * from finish();
rollback;
